class Solution {
public:
    int maxPossibleScore(vector<int>& start, int d) {
        sort(start.begin(), start.end());
        int n = start.size();
        auto ok = [&](long long m) {
            long long prev = start[0];
            for (int i = 1; i < n; i++) {
                long long need = prev + m;
                if (need > (long long)start[i] + d) return false;
                prev = max(need, (long long)start[i]);
            }
            return true;
        };
        long long lo = 0, hi = ((long long)start[n-1] + d - start[0]) / (n - 1);
        while (lo < hi) {
            long long mid = (lo + hi + 1) / 2;
            if (ok(mid)) lo = mid;
            else hi = mid - 1;
        }
        return (int)lo;
    }
};

