class Solution {
    public int maxPossibleScore(int[] start, int d) {
        Arrays.sort(start);
        int n = start.length;
        long lo = 0, hi = ((long) start[n - 1] + d - start[0]) / (n - 1);
        while (lo < hi) {
            long mid = (lo + hi + 1) / 2;
            if (ok(start, d, mid)) lo = mid;
            else hi = mid - 1;
        }
        return (int) lo;
    }
    private boolean ok(int[] start, int d, long m) {
        long prev = start[0];
        for (int i = 1; i < start.length; i++) {
            long need = prev + m;
            if (need > (long) start[i] + d) return false;
            prev = Math.max(need, start[i]);
        }
        return true;
    }
}

