var maxPossibleScore = function(start, d) {
    start.sort((a, b) => a - b);
    const n = start.length;
    const ok = (m) => {
        let prev = start[0];
        for (let i = 1; i < n; i++) {
            const need = prev + m;
            if (need > start[i] + d) return false;
            prev = Math.max(need, start[i]);
        }
        return true;
    };
    let lo = 0, hi = Math.floor((start[n - 1] + d - start[0]) / (n - 1));
    while (lo < hi) {
        const mid = Math.floor((lo + hi + 1) / 2);
        if (ok(mid)) lo = mid;
        else hi = mid - 1;
    }
    return lo;
};
